  1→/**
  2→ * Public API endpoint for the storefront zip code widget.
  3→ *
  4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
  5→ * to check whether a zip code is serviceable.
  6→ *
  7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
  8→ *
  9→ * Response:
 10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
 11→ *   200 { allowed: false, message: "..." }
 12→ *   400 { error: "Missing shop or zip parameter" }
 13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
 14→ */
 15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { normalizeZipCode } from "../utils/zip";
 18→
 19→const CORS_HEADERS = {
 20→  "Access-Control-Allow-Origin": "*",
 21→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 22→  "Access-Control-Allow-Headers": "Content-Type",
 23→  "Content-Type": "application/json",
 24→};
 25→
 26→// Applied only to successful (allowed) ZIP check responses to reduce DB load
 27→// for repeated lookups of the same ZIP code from the same storefront visitor.
 28→const SUCCESS_HEADERS = {
 29→  ...CORS_HEADERS,
 30→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
 31→};
 32→
 33→// Short cache for denied/not-found responses so merchants see changes quickly
 34→// (e.g. when they add a new ZIP code it takes effect within 5 seconds).
 35→const DENY_HEADERS = {
 36→  ...CORS_HEADERS,
 37→  "Cache-Control": "no-cache, max-age=5",
 38→};
 39→
 40→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
 41→
 42→async function handleZipCheck(shop: string | null, zip: string | null) {
 43→  if (!shop || !zip) {
 44→    return new Response(
 45→      JSON.stringify({ error: "Missing shop or zip parameter" }),
 46→      { status: 400, headers: CORS_HEADERS },
 47→    );
 48→  }
 49→
 50→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 51→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
 52→    return new Response(
 53→      JSON.stringify({ error: "Invalid shop parameter" }),
 54→      { status: 400, headers: CORS_HEADERS },
 55→    );
 56→  }
 57→
 58→  // Enforce input length limits to prevent abuse
 59→  if (zip.length > 20) {
 60→    return new Response(
 61→      JSON.stringify({ error: "Invalid zip code" }),
 62→      { status: 400, headers: CORS_HEADERS },
 63→    );
 64→  }
 65→
 66→  const normalizedZip = normalizeZipCode(zip);
 67→
 68→  try {
 69→  const zipRecord = await db.zipCode.findUnique({
 70→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
 71→  });
 72→
 73→  // Fetch widget config for custom messages (falls back to defaults)
 74→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
 75→
 76→  // Fetch shop settings to determine default behavior for unlisted zip codes
 77→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
 78→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
 79→
 80→  if (!zipRecord || !zipRecord.isActive) {
 81→    const notFoundMsg =
 82→      widgetConfig?.notFoundMessage ??
 83→      "We currently do not ship to this ZIP code.";
 84→
 85→    // If the zip is simply not in the list (not inactive) and the merchant
 86→    // has set defaultBehavior to "allow", treat it as an allowed zip
 87→    if (!zipRecord && defaultBehavior === "allow") {
 88→      const successMsg =
 89→        widgetConfig?.successMessage ?? "We deliver to your area!";
 90→      return new Response(
 91→        JSON.stringify({
 92→          allowed: true,
 93→          message: successMsg,
 94→          eta: null,
 95→          zone: null,
 96→          codAvailable: null,
 97→          returnPolicy: null,
 98→          showWaitlist: false,
 99→          waitlistCount: 0,
100→          cutoffTime: null,
101→          daysOfWeek: null,
102→        }),
103→        { status: 200, headers: SUCCESS_HEADERS },
104→      );
105→    }
106→
107→    // Social proof: count how many customers are waiting for this ZIP
108→    let waitlistCount = 0;
109→    try {
110→      waitlistCount = await db.waitlistEntry.count({
111→        where: { shop, zipCode: normalizedZip, status: "waiting" },
112→      });
113→    } catch {
114→      waitlistCount = 0;
115→    }
116→
117→    if (!zipRecord) {
118→      return new Response(
119→        JSON.stringify({
120→          allowed: false,
121→          message: notFoundMsg,
122→          notFound: true,
123→          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
124→          waitlistCount,
125→        }),
126→        { status: 200, headers: DENY_HEADERS },
127→      );
128→    }
129→
130→    // Inactive zip — treat same as not found regardless of defaultBehavior
131→    return new Response(
132→      JSON.stringify({
133→        allowed: false,
134→        message: notFoundMsg,
135→        notFound: true,
136→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
137→        waitlistCount,
138→      }),
139→      { status: 200, headers: DENY_HEADERS },
140→    );
141→  }
142→
143→  if (zipRecord.type === "blocked") {
144→    const errorMsg =
145→      zipRecord.message ??
146→      widgetConfig?.errorMessage ??
147→      "Sorry, we don't deliver to this area yet.";
148→
149→    // Social proof: count how many customers are waiting for this ZIP
150→    let waitlistCount = 0;
151→    try {
152→      waitlistCount = await db.waitlistEntry.count({
153→        where: { shop, zipCode: normalizedZip, status: "waiting" },
154→      });
155→    } catch {
156→      waitlistCount = 0;
157→    }
158→
159→    return new Response(
160→      JSON.stringify({
161→        allowed: false,
162→        message: errorMsg,
163→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
164→        waitlistCount,
165→      }),
166→      { status: 200, headers: DENY_HEADERS },
167→    );
168→  }
169→
170→  // Fetch the most relevant active DeliveryRule for this zip.
171→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
172→  // Priority 2: rules that match by zone (with no explicit zip list).
173→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
174→  const zipCodeUpper = normalizedZip;
175→  const zipZone = zipRecord.zone ?? null;
176→
177→  // Fetch all active rules for the shop ordered by priority so we can apply
178→  // the matching logic in a single query result.
179→  const activeRules = await db.deliveryRule.findMany({
180→    where: { shop, isActive: true },
181→    orderBy: { priority: "asc" },
182→  });
183→
184→  let matchedRule: (typeof activeRules)[number] | null = null;
185→
186→  // Pass 1: explicit zip match — zipCodes field contains this zip code
187→  for (const rule of activeRules) {
188→    if (rule.zipCodes) {
189→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
190→      if (zips.includes(zipCodeUpper)) {
191→        matchedRule = rule;
192→        break;
193→      }
194→    }
195→  }
196→
197→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
198→  if (!matchedRule && zipZone) {
199→    for (const rule of activeRules) {
200→      if (
201→        rule.zone === zipZone &&
202→        (!rule.zipCodes || rule.zipCodes.trim() === "")
203→      ) {
204→        matchedRule = rule;
205→        break;
206→      }
207→    }
208→  }
209→
210→  // Allowed
211→  const successMsg =
212→    zipRecord.message ??
213→    widgetConfig?.successMessage ??
214→    "Great news! We deliver to your area.";
215→
216→  // ETA: prefer the zip-level eta, then fall back to the matched delivery rule's
217→  // estimatedDays so merchants only need to populate one place.
218→  const etaValue = zipRecord.eta ?? matchedRule?.estimatedDays ?? null;
219→
220→  return new Response(
221→    JSON.stringify({
222→      allowed: true,
223→      message: successMsg,
224→      eta: widgetConfig?.showEta ? etaValue : null,
225→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
226→      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
227→      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
228→      showWaitlist: false,
229→      waitlistCount: 0,
230→      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
231→      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
232→    }),
233→    { status: 200, headers: SUCCESS_HEADERS },
234→  );
235→  } catch (err) {
236→    console.error("[api.zip-check] Unhandled error for shop=%s zip=%s:", shop, zip, err);
237→    return new Response(
238→      JSON.stringify({ error: "Internal server error" }),
239→      { status: 500, headers: CORS_HEADERS },
240→    );
241→  }
242→}
243→
244→// Handle GET requests: ?shop=...&zip=...
245→export const loader = async ({ request }: LoaderFunctionArgs) => {
246→  const url = new URL(request.url);
247→
248→  // Handle CORS preflight
249→  if (request.method === "OPTIONS") {
250→    return new Response(null, { status: 204, headers: CORS_HEADERS });
251→  }
252→
253→  const shop = url.searchParams.get("shop");
254→  const zip = url.searchParams.get("zip");
255→  return handleZipCheck(shop, zip);
256→};
257→
258→// Handle POST requests with JSON body: { shop, zip }
259→export const action = async ({ request }: ActionFunctionArgs) => {
260→  let shop: string | null = null;
261→  let zip: string | null = null;
262→
263→  try {
264→    const body = await request.json();
265→    shop = body?.shop ?? null;
266→    zip = body?.zip ?? null;
267→  } catch {
268→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
269→      status: 400,
270→      headers: CORS_HEADERS,
271→    });
272→  }
273→
274→  return handleZipCheck(shop, zip);
275→};
